    customerId: 'C-001', // Gold (5%)
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  // Line total: 5 * 8500 = 42500
  // Discount: 42500 * 5 / 100 = 2125
  // Total: 42500 - 2125 = 40375
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.total, 40375);
});

test('addLine applies tier discount to new lines', () => {
  const r = createInvoice({
    customerId: 'C-001', // Gold (5%)
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 5); // tier discount
});

test('addLine explicit discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // Gold (5%)
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'COPY-HOUR', qty: 2, discountPercent: 12 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 12); // explicit discount
